INSERT INTO `camp_email_reminder_template` (`content`, `created_at`, `updated_at`) VALUES
    (CAST('{"name":"ชวนเข้าร่วมค่าย","audience":"NOT_JOINED","daysBefore":7,"subject":"อย่าลืมเข้าร่วมค่าย [ชื่อค่าย]","heading":"อย่าลืมเข้าร่วมค่าย [ชื่อค่าย]","body":"ขณะนี้คุณยังไม่ได้ยืนยันเข้าร่วมค่าย กรุณาเข้าร่วมผ่านระบบก่อนค่ายเริ่ม","action":"กดเข้าร่วมค่ายในระบบ","buttonLabel":"เข้าร่วมค่าย"}' AS JSON), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
    (CAST('{"name":"ชวนเข้าร่วมครั้งสุดท้าย","audience":"NOT_JOINED","daysBefore":2,"subject":"เหลือเวลาอีกไม่นาน! [ชื่อค่าย] จะเริ่ม[อีกกี่วัน]","heading":"ยังทันเข้าร่วม [ชื่อค่าย]","body":"ค่ายจะเริ่ม[อีกกี่วัน] แต่คุณยังไม่ได้กดเข้าร่วม\\n\\nกรุณากดเข้าร่วมผ่านระบบโดยเร็ว เพื่อให้ครูจัดเตรียมรถและที่พักได้ครบ","action":"กดเข้าร่วมค่ายในระบบ","buttonLabel":"เข้าร่วมค่ายตอนนี้"}' AS JSON), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
    (CAST('{"name":"เตรียมของเข้าค่าย","audience":"PARTICIPANTS","daysBefore":5,"subject":"เตรียมของให้พร้อมสำหรับ [ชื่อค่าย]","heading":"เตรียมของให้พร้อมสำหรับ [ชื่อค่าย]","body":"อีก [จำนวนวันที่เหลือ] วันจะถึงวันเข้าค่าย ลองเช็กของที่ต้องเตรียมไว้แต่เนิ่น ๆ เช่น เสื้อผ้า ยาประจำตัว และของใช้ส่วนตัว\\n\\nรายละเอียดและสิ่งที่ต้องเตรียมทั้งหมดดูได้ในระบบ","action":"ตรวจสอบรายการของที่ต้องเตรียม","buttonLabel":"ดูรายละเอียดค่าย"}' AS JSON), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
    (CAST('{"name":"เตือนเตรียมตัว","audience":"PARTICIPANTS","daysBefore":3,"subject":"ค่าย [ชื่อค่าย] ใกล้เริ่มแล้ว","heading":"ค่าย [ชื่อค่าย] ใกล้เริ่มแล้ว","body":"เตรียมตัวให้พร้อมสำหรับค่ายที่กำลังจะเริ่ม และตรวจสอบรายละเอียดล่าสุดได้จากระบบ","action":"เตรียมตัวเข้าค่าย","buttonLabel":"ดูรายละเอียดค่าย"}' AS JSON), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
    (CAST('{"name":"พรุ่งนี้เข้าค่าย","audience":"PARTICIPANTS","daysBefore":1,"subject":"พรุ่งนี้แล้ว! [ชื่อค่าย]","heading":"ค่าย [ชื่อค่าย] เริ่มพรุ่งนี้","body":"ค่ายจะเริ่มในวันพรุ่งนี้ ([วันเริ่มค่าย]) ที่ [สถานที่]\\n\\nกรุณาตรวจสอบเวลานัดหมาย จุดขึ้นรถ และของที่ต้องเตรียมให้เรียบร้อย พักผ่อนให้เพียงพอนะ","action":"ตรวจสอบเวลานัดหมายและจุดขึ้นรถ","buttonLabel":"ดูรายละเอียดค่าย"}' AS JSON), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
